class Solution { int leftHeight(TreeNode* node){int h=0;while(node){++h;node=node->left;}return h;}int rightHeight(TreeNode* node){int h=0;while(node){++h;node=node->right;}return h;}public:int countNodes(TreeNode* root){if(!root)return 0;int left=leftHeight(root),right=rightHeight(root);if(left==right)return (1LL<<left)-1;return 1+countNodes(root->left)+countNodes(root->right);} };
